# Plate solution of the chart, fitted by HaslaLab to 338 Hipparcos stars (rms 0.4 px): Lambert azimuthal
# equal-area, centre RA 305.868 deg, Dec +32.168 deg, 17.444 px per degree, turned 181 deg (north down, east right).
FIT = (5.338404505939538, 0.5614414326468079, 999.4884096742821, -3.1593670712016086, 494.32105129189114, 927.3416980769806)


def proj(ra, de):
    a0, d0, s, th, tx, ty = FIT
    r, d = ra * D2R - a0, de * D2R
    cosc = math.sin(d0) * math.sin(d) + math.cos(d0) * math.cos(d) * math.cos(r)
    if cosc < -0.5:
        return None
    k = math.sqrt(2 / (1 + cosc))
    X = -math.cos(d) * math.sin(r) * k
    Y = (math.cos(d0) * math.sin(d) - math.sin(d0) * math.cos(d) * math.cos(r)) * k
    return tx + s * (X * math.cos(th) - Y * math.sin(th)), ty - s * (X * math.sin(th) + Y * math.cos(th))


